from runtime_sdk import NodeContext


def run(ctx: NodeContext):
    """文档加载：把 pdf / docx / md / txt / csv 抽成纯文本。"""
    path = ctx.params.get("path") or ctx.text.strip()
    if not path:
        raise ValueError("doc_loader 需要指定文件路径（可写在参数 path 里）")
