def merger_6(state: AgentState) -> dict:
    """查询+索引 —— 把多路结果合并成一份。"""
    items = state.get("results")
    if not items:
        items = [state.get("data", "")]
    if isinstance(items, str):
        items = [items]
    parts, seen = [], set()
    for it in items:
        s = it if isinstance(it, str) else json.dumps(it, ensure_ascii=False)
        s = (s or "").strip()
        if s and s not in seen:
            seen.add(s)
            parts.append(s)
    merged = "\\n\\n".join(parts)
    return {"data": merged, "merged_count": len(parts)}

